        WHEN (NEW.user_id IS NOT OLD.user_id AND (NOT EXISTS (SELECT 1 FROM users WHERE id = NEW.user_id)))
        BEGIN
          SELECT RAISE(ABORT, 'account reference does not exist');
        END;

